(() => {
 const box=document.querySelector('.livebox');
 const field=document.createElement('label');field.htmlFor='speechEngine';field.textContent='Reconhecimento de voz';
 const select=document.createElement('select');select.id='speechEngine';
 for(const [value,label]of [['browser','Reconhecimento do navegador'],['device','Whisper no dispositivo — precisão (experimental)'],['local','Whisper local — experimental']]){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}
 field.append(select);const status=document.createElement('p');status.id='asrStatus';status.setAttribute('role','status');const check=document.createElement('button');check.textContent='Preparar reconhecimento';check.id='checkASR';box.append(field,status,check);const cancel=document.createElement('button');cancel.id='cancelRecognitionPreparation';cancel.textContent='Cancelar preparação';cancel.hidden=true;cancel.onclick=()=>window.deviceASR?.abort('Preparação cancelada. Você pode escolher Reconhecimento do navegador.');box.append(cancel);
 const punctuationLabel=document.createElement('label');punctuationLabel.className='original-toggle';const punctuationToggle=document.createElement('input');punctuationToggle.type='checkbox';punctuationToggle.id='autoPunctuation';punctuationToggle.checked=true;punctuationLabel.append(punctuationToggle,document.createTextNode('Pontuação automática'));const punctuationStatus=document.createElement('small');punctuationStatus.id='punctuationStatus';punctuationStatus.textContent='Preserva as palavras. Vírgulas e perguntas são estimadas pelo contexto.';box.append(punctuationLabel,punctuationStatus);
 let loaded=false,job,modeGeneration=0;
 async function health(){status.textContent='Verificando motor…';try{const res=await fetch('/api/asr/health');const data=await res.json();loaded=!!data.ready;status.textContent=loaded?`Pronto: ${data.model} · ${data.device}. Áudio processado no computador da sala.`:data.error||'Modelo carregando. Aguarde e verifique novamente.';punctuationStatus.textContent=data.punctuationReady?'Pontuação local pronta. Preserva as palavras; perguntas são estimadas pelo contexto.':'Pontuação carregando ou indisponível. O texto bruto será preservado.'}catch{loaded=false;status.textContent='Motor local indisponível. O reconhecimento do navegador continua disponível.'}return loaded}
 const privacy=box.querySelector('small');const browserPrivacy=privacy?.textContent;
 window.deviceASR?.onProgress(p=>{status.textContent=window.asrUtils.progressLabel(p)});
 async function prepare(){if(select.value==='device'){await window.deviceASR.prepare();status.textContent='Whisper no dispositivo pronto e validado. Recomendado para este dispositivo — experimental.'}else if(select.value==='local'){if(!await health())throw Error('Motor local ainda indisponível.')}else status.textContent='O reconhecimento do navegador está disponível ao ligar o microfone.'}
 check.onclick=async()=>{check.disabled=true;select.disabled=true;status.textContent='Preparando reconhecimento…';cancel.hidden=select.value!=='device';try{await prepare()}catch(error){status.textContent=error.message}finally{check.disabled=false;select.disabled=false;cancel.hidden=true}};select.onchange=()=>{if(select.value==='device'){status.textContent='Clique em Preparar reconhecimento. O modelo será baixado e validado neste dispositivo.';if(privacy)privacy.textContent='Whisper processa o áudio neste dispositivo. Áudio não é enviado ao servidor nem gravado.'}else if(select.value==='local'){health();if(privacy)privacy.textContent='Whisper processa o áudio temporariamente no computador que hospeda a sala. Somente a transcrição é salva.'}else{status.textContent='Reconhecimento do navegador selecionado.';if(privacy)privacy.textContent=browserPrivacy}};status.textContent='Escolha o motor antes de ligar o microfone.';
 function wav(parts,count,rate){const samples=new Float32Array(count);let offset=0;for(const part of parts){samples.set(part,offset);offset+=part.length}const buffer=new ArrayBuffer(44+count*2),view=new DataView(buffer);const text=(at,str)=>{for(let i=0;i<str.length;i++)view.setUint8(at+i,str.charCodeAt(i))};text(0,'RIFF');view.setUint32(4,36+count*2,true);text(8,'WAVE');text(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,rate,true);view.setUint32(28,rate*2,true);view.setUint16(32,2,true);view.setUint16(34,16,true);text(36,'data');view.setUint32(40,count*2,true);for(let i=0;i<count;i++)view.setInt16(44+i*2,Math.max(-1,Math.min(1,samples[i]))*(samples[i]<0?32768:32767),true);return buffer}
 async function start(stream,config){
  const useDevice=select.value==='device';if(useDevice){if(!window.deviceASR?.ready())throw new Error('Clique em Preparar reconhecimento antes de ligar o microfone.')}else if(!await health())throw new Error('Whisper local não está pronto. Selecione Navegador ou aguarde o modelo.');
  const context=new AudioContext();try{await context.audioWorklet.addModule('/capture-processor.js');await context.resume()}catch(error){await context.close();throw error}
  const source=context.createMediaStreamSource(stream);const capture=new AudioWorkletNode(context,'classroom-capture',{channelCount:1,channelCountMode:'explicit'});const mute=context.createGain();mute.gain.value=0;
  const generation=++modeGeneration;const current={context,source,capture,mute,parts:[],samples:0,power:0,quiet:0,queue:Promise.resolve(),queued:0,pendingStop:false,config};job=current;select.disabled=true;check.disabled=true;
  function flush(){
   const count=current.samples,parts=current.parts,power=current.power;current.parts=[];current.samples=0;current.power=0;current.quiet=0;
   if(!count||Math.sqrt(power/count)<0.002||count/context.sampleRate<0.25)return;
   if(current.queued>=2){status.textContent='Motor atrasado. Um trecho não pôde ser processado.';config.gap('Trecho de áudio não processado: Whisper atrasado.');return}
   let audio;if(useDevice){const mono=new Float32Array(count);let at=0;for(const part of parts){mono.set(part,at);at+=part.length}audio=window.asrUtils.resample(mono,context.sampleRate)}else audio=wav(parts,count,context.sampleRate);current.queued++;
   current.queue=current.queue.then(async()=>{
    try{status.textContent=useDevice?'Transcrevendo neste dispositivo…':'Transcrevendo no computador da sala…';config.phase('Reconhecendo com Whisper…');
     const result=useDevice?await window.deviceASR.transcribe(audio,config.language):await config.transcribe(audio);
     if(generation!==modeGeneration)return;
     if(result.text)await config.text(result.text);
     if(result.discardedSegments)config.gap('Trecho de baixa confiança omitido pelo reconhecimento local.');
     status.textContent=`${result.model} · último trecho: ${(result.processingMs/1000).toFixed(1)}s de processamento.`;
     if(!result.text)config.phase('Ouvindo — nenhum texto reconhecido neste trecho');
    }catch(error){if(generation!==modeGeneration)return;status.textContent=error.message+' Desligue o microfone para escolher outro motor. O áudio da chamada continua ativo.';if(!current.failed){current.failed=true;await config.gap('Falha no reconhecimento Whisper: '+error.message)}}finally{current.queued--}
   });
  }
  capture.port.onmessage=e=>{if(current.pendingStop||current.failed)return;const part=e.data;current.parts.push(part);current.samples+=part.length;let energy=0;for(const sample of part)energy+=sample*sample;current.power+=energy;current.quiet=Math.sqrt(energy/part.length)<0.003?current.quiet+part.length:0;if((current.samples>=context.sampleRate*2&&current.quiet>=context.sampleRate*0.3)||current.samples>=context.sampleRate*10)flush()};
  current.flush=flush;source.connect(capture);capture.connect(mute);mute.connect(context.destination);status.textContent='Whisper ouvindo. Transcreve nas pausas; trechos de 2 a 10 segundos.';
 }
 async function stop(){const current=job;if(!current)return;job=null;current.pendingStop=true;current.capture.port.onmessage=null;current.source.disconnect();current.capture.disconnect();current.mute.disconnect();await current.context.close();if(current.queued>=2)await current.queue;current.flush();await current.queue;select.disabled=false;check.disabled=false;status.textContent='Whisper parado. Últimos trechos processados.'}
 function abort(){const current=job;if(!current)return;modeGeneration++;job=null;current.pendingStop=true;current.source.disconnect();current.capture.disconnect();current.mute.disconnect();current.context.close().catch(()=>{});select.disabled=false;check.disabled=false;}
 window.localASR={prepare,selected:()=>select.value==='local'||select.value==='device',engine:()=>select.value,punctuationEnabled:()=>punctuationToggle.checked,setActive:active=>{select.disabled=active;check.disabled=active},start,stop,abort,health,cloudMode(){select.value='browser';for(const option of select.children)if(option.value==='local')option.hidden=true;punctuationToggle.checked=false;punctuationLabel.hidden=true;punctuationStatus.textContent='A pontuação nativa do navegador é preservada. A camada Python está disponível apenas no localhost.';status.textContent='Whisper no dispositivo disponível após preparação. O reconhecimento do navegador continua como alternativa.';if(privacy)privacy.textContent='O provedor do navegador pode receber áudio. O texto é criptografado no dispositivo antes do envio ao banco.'}};
})();
